# Now let's identify which song IDs in all playlists match the old songs list (old_songs).
# We'll match by both title and all artist names (case-insensitive, ignoring order).
# Build a set of song_ids_to_archive and a mapping from playlist_id to the list of song_ids to remove.

def normalize(s):
    return s.strip().lower()

old_song_keys = set()
for entry in old_songs:
    # Each entry is like "Song Title - Artist1, Artist2"
    if "-" in entry:
        title, artists = entry.split("-", 1)
        title = normalize(title)
        artist_names = sorted([normalize(a) for a in artists.split(",")])
        key = (title, tuple(artist_names))
        old_song_keys.add(key)

